const worker=`import {observeOneOutcome,observeOutcomes} from './lib/sentinel/outcome-collector';import {assessDiscoveryBatch} from './lib/sentinel/discovery-case';import {assessDiscoveryQueue} from './lib/sentinel/discovery-case';import {collectDiscovery} from './lib/sentinel/discovery-collector';import * as discovery from './app/api/discovery/route';import * as companyNews from './app/api/company-news/route';import * as quote from './app/api/stock-quote/route';import * as brief from './app/api/investment-brief/route';import * as paper from './app/api/paper/route';import * as practice from './app/api/practice/route';import * as practiceRisk from './app/api/practice-risk/route';import * as autoPractice from './app/api/auto-practice/route';import * as ideas from './app/api/ideas/route';import * as following from './app/api/following/route';import * as researchTeam from './app/api/research-team/route';import * as caseContext from './app/api/case-context/route';import * as explain from './app/api/filing-explanation/route';import * as mcp from './app/mcp/route';import * as watch from './app/api/watchlist/route';import * as company from './app/api/company/route';import * as criteria from './app/api/criteria/route';import * as journal from './app/api/journal/route';import * as market from './app/api/market/route';import * as refresh from './app/api/refresh/route';import * as shadowComparison from './app/api/shadow-comparison/route';import * as morningBrief from './app/api/morning-brief/route';import * as pipeline from './app/api/pipeline/route';import {evaluate} from './lib/sentinel/criteria';import {parseFacts,derive,selectFacts} from './lib/sentinel/financial';export default {async fetch(request,env){globalThis.testUser=request.headers.get('x-test-user');const p=new URL(request.url).pathname;if(p==='/observe-outcome')return Response.json(await observeOneOutcome(globalThis.testUser));if(p==='/observe-outcomes')return Response.json(await observeOutcomes(globalThis.testUser));if(p==='/assess-batch'){const q=new URL(request.url).searchParams;return Response.json(await assessDiscoveryBatch(globalThis.testUser,'research@example.test',{...(q.has('limit')?{limit:Number(q.get('limit'))}:{}),...(q.has('budget')?{budgetMs:Number(q.get('budget'))}:{})}))}if(p==='/assess-discovery')return Response.json(await assessDiscoveryQueue(globalThis.testUser,'research@example.test'));if(p==='/collect-discovery')return Response.json(await collectDiscovery(globalThis.testUser));if(p==='/pure'){const x=await request.json();return Response.json(evaluate(x.predicate,x.figures,x.filings,x.asOf))}const routes={'/discovery':discovery,'/company-news':companyNews,'/stock-quote':quote,'/brief':brief,'/paper':paper,'/practice':practice,'/practice-risk':practiceRisk,'/auto-practice':autoPractice,'/ideas':ideas,'/following':following,'/research-team':researchTeam,'/case-context':caseContext,'/explain':explain,'/mcp':mcp,'/watch':watch,'/company':company,'/criteria':criteria,'/journal':journal,'/market':market,'/refresh':refresh,'/shadow-comparison':shadowComparison,'/morning-brief':morningBrief,'/pipeline':pipeline};return routes[p][request.method](request)}};`;
const built=await esbuild.build({stdin:{contents:worker,resolveDir:process.cwd(),loader:'ts'},bundle:true,write:false,platform:'neutral',format:'esm',target:'es2022',external:['cloudflare:workers'],plugins:[{name:'identity',setup(b){b.onResolve({filter:/chatgpt-auth$/},()=>({path:'identity',namespace:'identity'}));b.onLoad({filter:/.*/,namespace:'identity'},()=>({contents:'export async function getChatGPTUser(){return globalThis.testUser?{userId:globalThis.testUser,email:"research@example.test"}:null}',loader:'js'}))}}]});
