await test('the refresh reports each stage; a stage selector runs only what was asked; failures are visible and recorded',async()=>{
 const owner='pipe-owner';
 const mcpCall=async(args,user=owner)=>{const r=await mf.dispatchFetch('http://localhost/mcp',{method:'POST',headers:{'Content-Type':'application/json','oai-authenticated-user-id':user,'oai-authenticated-user-email':'research@example.test'},body:JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'refresh_saved_company_filings',arguments:args}})});const j=await r.json();return {isError:j.result.isError,text:j.result.content[0].text,payload:(()=>{try{return JSON.parse(j.result.content[0].text)}catch{return null}})()};};
 // A bad selector runs nothing and records nothing.
 const bad=await mcpCall({stages:['trade']});assert.equal(bad.isError,true);assert.match(bad.text,/Nothing was run/);assert.equal((await db.prepare("SELECT COUNT(*) n FROM signal_log WHERE owner=? AND kind='pipeline_run'").bind(owner).first()).n,0);
 // Only the assessment stage: the others are reported as skipped, not run, and their sections are absent.
 const only=await mcpCall({stages:['assessment']});assert.equal(only.isError,false);assert.equal(only.payload.pipeline.stages.length,7,'every stage has a record');
 assert.deepEqual(only.payload.pipeline.stages.filter(x=>x.status!=='skipped').map(x=>x.stage),['assessment']);assert.equal(only.payload.news,undefined);assert.equal(only.payload.discovery,undefined);assert.equal(only.payload.autoPractice,undefined);assert.equal(only.payload.discoveryAssessment.status,'idle');assert.equal(only.payload.pipeline.status,'idle');
 // The default run is unchanged in shape: every stage runs, in the original order, each with a time and a status; the error flag matches the failed list.
 const all=await mcpCall({});const stages=all.payload.pipeline.stages;assert.deepEqual(stages.map(x=>x.stage),['filings','news','discovery','assessment','outcomes','practice','experiment']);assert.ok(stages.every(x=>x.status!=='skipped'&&typeof x.elapsedMs==='number'));
 assert.equal(all.isError,all.payload.pipeline.failed.length>0);assert.deepEqual(all.payload.pipeline.failed,stages.filter(x=>x.status==='failed').map(x=>x.stage));assert.ok(all.payload.discovery&&all.payload.discoveryAssessment&&all.payload.outcomeObservation&&all.payload.practiceMark&&all.payload.autoPractice,'the original response sections are all still present');
 // Both runs are recorded, append-only, and readable only by their owner.
 const runs=(await req('/pipeline','GET',undefined,owner)).data.runs;assert.equal(runs.length,2);assert.deepEqual(runs.map(r=>r.requested.length).sort(),[1,7]);assert.ok(runs.every(r=>r.version==='pipeline-v1'&&typeof r.elapsedMs==='number'));assert.ok(!JSON.stringify(runs).includes('research@example.test'),'no contact email is stored');
 assert.equal((await req('/pipeline','GET',undefined,'someone-else')).data.runs.length,0,'owner isolation');
 const row=await db.prepare("SELECT id FROM signal_log WHERE owner=? AND kind='pipeline_run' LIMIT 1").bind(owner).first();await assert.rejects(db.prepare("UPDATE signal_log SET body='{}' WHERE id=?").bind(row.id).run(),/immutable/);await assert.rejects(db.prepare("DELETE FROM signal_log WHERE id=?").bind(row.id).run(),/immutable/);
});
